25	+namespace seed_a_backend.Api.Data;
26	+
27	+/// <summary>
28	+/// Zentralisiert die Europe/Berlin-Zeitzonenlogik, die sowohl der Anfangsdatenbestand-Parser
29	+/// (<see cref="OffsetlosAlsEuropaBerlinZeitpunktConverter"/>) als auch der Datumsbereich-Filter
30	+/// der Veranstaltungsliste benötigen, statt sie zweimal zu duplizieren.
31	+/// </summary>
32	+public static class EuropaBerlinZeitzone
33	+{
34	+    public static readonly TimeZoneInfo Instanz = TimeZoneInfo.FindSystemTimeZoneById("Europe/Berlin");
35	+
36	+    public static DateTimeOffset Tagesbeginn(DateOnly datum)
37	+    {
38	+        var lokaleZeit = datum.ToDateTime(TimeOnly.MinValue);
39	+        return new DateTimeOffset(lokaleZeit, Instanz.GetUtcOffset(lokaleZeit));
40	+    }
41	+
42	+    public static DateTimeOffset Tagesende(DateOnly datum)
43	+    {
44	+        var lokaleZeit = datum.ToDateTime(TimeOnly.MaxValue);
45	+        return new DateTimeOffset(lokaleZeit, Instanz.GetUtcOffset(lokaleZeit));
46	+    }
47	+}
