+    public static DateTimeOffset Tagesbeginn(DateOnly datum)
+    {
+        var lokaleZeit = datum.ToDateTime(TimeOnly.MinValue);
+        return new DateTimeOffset(lokaleZeit, Instanz.GetUtcOffset(lokaleZeit));
