    public static DateTimeOffset Tagesende(DateOnly datum)
    {
        var lokaleZeit = datum.ToDateTime(TimeOnly.MaxValue);
        return new DateTimeOffset(lokaleZeit, Instanz.GetUtcOffset(lokaleZeit));
    }
}

